package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b int
	fmt.Fscan(in, &a, &b)

	// Days with different socks
	diff := a
	if b < a {
		diff = b
	}

	// Remaining socks after wearing different pairs
	remaining := a + b - 2*diff

	// Days with same socks
