	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b int
	fmt.Fscan(in, &a, &b)

	// Days with different socks
	diffDays := min(a, b)

	// Remaining socks after wearing different pairs
	remaining := abs(a-b)

	// Days with same socks
	sameDays := remaining / 2

	fmt.Println(diffDays, sameDays)
}

func min(x, y int) int {
	if x < y {
		return x
	}
	return y
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}
